// Package locale embeds the translation catalogs, one directory per
// language: <lang>/LC_MESSAGES/<domain>.po.
//
//   - cms: contestant and ranking sites. The catalogs are the ones of CMS
//     (cms/locale), kept with the same msgids so they stay reusable.
//   - admin: administration site. Every message must have a Spanish
//     translation (enforced by TestAdminSpanishIsComplete).
//
// cms.pot and admin.pot are regenerated by `make generate`.
package locale

import "embed"

//go:generate go run ../cmd/i18n-extract -domain admin -out admin.pot ../internal/adminweb

// FS holds every catalog.
//
//go:embed */LC_MESSAGES/*.po
var FS embed.FS

// Domains of the catalogs.
const (
	DomainContest = "cms"
	DomainAdmin   = "admin"
)
